 /** Split a template into text and tag tokens. See README.md. */
 export function tokenize(template: string): Token[] {
-  throw new Error("not implemented");
+  const tokens: Token[] = [];
+  let pos = 0;
+  while (pos < template.length) {
+    const open = template.indexOf("{{", pos);
+    if (open === -1) {
+      tokens.push({ kind: "text", text: template.slice(pos) });
+      break;
+    }
+    if (open > pos) tokens.push({ kind: "text", text: template.slice(pos, open) });
+
+    const raw = template.startsWith("{{{", open);
+    const openLength = raw ? 3 : 2;
+    const closer = raw ? "}}}" : "}}";
+    const close = template.indexOf(closer, open + openLength);
+    if (close === -1) throw new Error("unterminated tag");
+
+    const inner = template.slice(open + openLength, close).trim();
+    pos = close + closer.length;
+
+    if (!raw) {
+      const ifMatch = /^#if\s+(\S.*)$/.exec(inner);
+      if (ifMatch) {
+        tokens.push({ kind: "if", path: ifMatch[1] });
+        continue;
+      }
+      if (inner === "/if") {
+        tokens.push({ kind: "end" });
+        continue;
+      }
+      if (inner === "else") {
+        tokens.push({ kind: "else" });
+        continue;
+      }
+    }
+    tokens.push({ kind: "value", expr: inner, raw });
+  }
+  return tokens;
 }
